	local serverEndpoint = syncapi.ServerEndpoint	

	local function invokeServer(args)	
	    serverEndpoint:InvokeServer(unpack(args))	
	end	

	local function destroyPart(part)	
	    invokeServer({ "Remove", { part } })	
