	local function buildModel(model)	
	    local destination = Workspace	

	    for _, part in ipairs(model:GetDescendants()) do	
	        task.spawn(function()	
	            local partType	
	            if part:IsA("MeshPart") then	
	                partType = "Normal"	
	            elseif part:IsA("Part") then	
	                if part.Shape == Enum.PartType.Block then partType = "Normal"	
	                elseif part.Shape == Enum.PartType.Ball then partType = "Ball"	
	                elseif part.Shape == Enum.PartType.Cylinder then partType = "Cylinder" end	
	            elseif part:IsA("WedgePart") then partType = "Wedge"	
	            elseif part:IsA("Seat") then partType = "Seat"	
	            elseif part:IsA("VehicleSeat") then partType = "VehicleSeat"	
	            elseif part:IsA("TrussPart") then partType = "Truss"	
	            elseif part:IsA("SpawnLocation") then partType = "Spawn"	
	            end	

	            if partType then	
	                local created = serverEndpoint:InvokeServer("CreatePart", partType, part.CFrame, destination)	

	                -- ALL MAIN PROPERTIES + MESH TOGETHER	
	                task.spawn(function()	
	                    -- Resize	
	                    serverEndpoint:InvokeServer("SyncResize", { { Part = created, CFrame = part.CFrame, Size = part.Size } })	

	                    -- Material + Transparency	
	                    serverEndpoint:InvokeServer("SyncMaterial", { { Part = created, Material = part.Material, Transparency = part.Transparency } })	

	                    -- Color	
	                    if part.Color ~= BrickColor.new("Medium stone grey").Color then	
	                        serverEndpoint:InvokeServer("SyncColor", { { Part = created, Color = part.Color, UnionColoring = true } })	
	                    end	

	                    -- Collision	
	                    serverEndpoint:InvokeServer("SyncCollision", { { Part = created, CanCollide = part.CanCollide } })	

	                    -- Mesh (if MeshPart)	
	                    if part:IsA("MeshPart") then	
	                        serverEndpoint:InvokeServer("CreateMeshes", { { Part = created } })	
	                        serverEndpoint:InvokeServer("SyncMesh", { { Part = created, MeshId = part.MeshId, TextureId = part.TextureID, Scale = part.Size } })	
	                    end	
	                end)	

	                -- Textures & Decals	
	                for _, child in ipairs(part:GetChildren()) do	
	                    if child:IsA("Texture") then	
	                        task.spawn(function()	
	                            serverEndpoint:InvokeServer("CreateTextures", { { Part = created, Face = child.Face, TextureType = "Texture" } })	
	                            serverEndpoint:InvokeServer("SyncTexture", { { Part = created, Face = child.Face, TextureType = "Texture", StudsPerTileU = child.StudsPerTileU, StudsPerTileV = child.StudsPerTileV, Texture = child.Texture, Transparency = child.Transparency } })	
	                        end)	
	                    elseif child:IsA("Decal") then	
	                        task.spawn(function()	
	                            serverEndpoint:InvokeServer("CreateTextures", { { Part = created, Face = child.Face, TextureType = "Decal" } })	
	                            serverEndpoint:InvokeServer("SyncTexture", { { Part = created, Face = child.Face, TextureType = "Decal", Texture = child.Texture, Transparency = child.Transparency } })	
	                        end)	
	                    end	
	                end	

	                -- Lights	
	                local lightClasses = { "SpotLight", "PointLight" }	
	                for _, className in ipairs(lightClasses) do	
	                    local light = part:FindFirstChildOfClass(className)	
	                    if light then	
	                        task.spawn(function()	
	                            serverEndpoint:InvokeServer("CreateLights", { { Part = created, LightType = className } })	
	                            local lightProps = {	
	                                Part = created,	
	                                LightType = className,	
	                                Color = light.Color,	
	                                Range = light.Range,	
	                                Shadows = light.Shadows	
	                            }	
	                            if className == "SpotLight" then	
	                                lightProps.Face = light.Face	
	                                lightProps.Angle = light.Angle	
	                            end	
	                            serverEndpoint:InvokeServer("SyncLighting", { lightProps })	
	                        end)	
	                    end	
	                end	
	            end	
	        end)	
	    end	
	end	

